<?php use Clinica\Services\SessionService; $escape = static fn(mixed $v): string => htmlspecialchars((string)($v ?? ''), ENT_QUOTES | ENT_SUBSTITUTE, 'UTF-8'); ?>
<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Restablecer contraseña · Clínica Vida Salud</title><link rel="stylesheet" href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css"><link rel="stylesheet" href="/assets/css/app.css"></head><body class="login-page"><main class="login-form-area"><div class="login-form-inner"><h1>Establecer nueva contraseña</h1><?php if($message): ?><div class="alert alert-success"><?= $escape($message) ?></div><?php endif; ?><?php if($errors): ?><div class="alert alert-danger"><?= $escape(implode(' ', $errors)) ?></div><?php endif; ?><form method="post" action="/restablecer-contrasena"><input type="hidden" name="csrf" value="<?= $escape(SessionService::csrf()) ?>"><input type="hidden" name="token" value="<?= $escape($token) ?>"><label class="form-label" for="contrasena">Nueva contraseña</label><input class="form-control mb-3" type="password" id="contrasena" name="contrasena" minlength="8" maxlength="72" required><label class="form-label" for="confirmacion">Confirmar contraseña</label><input class="form-control mb-4" type="password" id="confirmacion" name="confirmacion" minlength="8" maxlength="72" required><button class="btn btn-clinic btn-lg w-100" type="submit">Actualizar contraseña</button></form><p class="mt-4"><a href="/login">Volver a iniciar sesión</a></p></div></main></body></html>
